<script setup>
import { ref,computed,onMounted } from 'vue';
import { useRoute } from 'vue-router';
import { api } from '../../services/api.js';
import { workspace } from '../../services/workspace.js';
import { notify,confirmDialog } from '../../services/notifications.js';
import { money,date,statuses,fulfillments } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';
const route=useRoute(),order=ref(null),loading=ref(true),busy=ref(false),error=ref(''),nextStatus=ref(''),nextFulfillment=ref(''),note=ref('');
const path=computed(()=>`/stores/${workspace.activeStoreId}/orders/${route.params.id}`),final=computed(()=>['paid','cancelled'].includes(order.value?.status)),isMP=computed(()=>order.value?.payment?.type==='mercadopago');
async function load(){try{const result=await api.get(path.value);order.value=result.order||result;nextStatus.value=order.value.status;nextFulfillment.value=order.value.fulfillmentStatus}catch(e){error.value=e.message}finally{loading.value=false}}
onMounted(load);
async function status(){if(nextStatus.value===order.value.status)return;if(['paid','cancelled'].includes(nextStatus.value)){const paid=nextStatus.value==='paid';if(!await confirmDialog({title:paid?'Confirmar pago · estado final':'Cancelar pedido · estado final',message:paid?'Este estado es final: el pedido no podrá volver a un estado anterior. Si incluye productos digitales, se enviarán al correo del cliente. Confirmá únicamente si verificaste el cobro.':'La cancelación es final: se liberará el stock reservado y el pedido no podrá reabrirse. Esta acción no ejecuta un reembolso del medio de pago.',confirmText:paid?'Confirmar pago':'Cancelar pedido',danger:!paid})){nextStatus.value=order.value.status;return}}
 busy.value=true;try{await api.put(`${path.value}/status`,{status:nextStatus.value,confirmFinal:['paid','cancelled'].includes(nextStatus.value),note:note.value});notify.success('Estado del pedido actualizado.');note.value='';await load()}catch(e){notify.error(e.message)}finally{busy.value=false}}
async function fulfillment(){busy.value=true;try{await api.put(`${path.value}/fulfillment`,{fulfillmentStatus:nextFulfillment.value,note:note.value});notify.success('Entrega actualizada.');note.value='';await load()}catch(e){notify.error(e.message)}finally{busy.value=false}}
async function verify(){busy.value=true;try{await api.post(`${path.value}/verify-payment`);await load();notify.info(order.value.status==='paid'?'Mercado Pago confirmó el pago.':'Verificación realizada. Revisá el estado actualizado del pedido.')}catch(e){notify.error(e.message)}finally{busy.value=false}}
async function resend(){busy.value=true;try{await api.post(`${path.value}/resend-digital`);notify.success('Se solicitó el reintento de la entrega digital.');await load()}catch(e){notify.error(e.message)}finally{busy.value=false}}
</script>
<template><div><RouterLink to="/app/orders" class="p-back-link"><Icon name="back" :size="14"/>Volver a pedidos</RouterLink><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><template v-else-if="order"><header class="p-page-header"><div><p class="p-eyebrow">CADA VENTA TIENE SU HISTORIA</p><h1>Pedido #{{order.number||order._id.slice(-6).toUpperCase()}}</h1><p>{{date(order.createdAt)}} · {{order.customer?.name}}</p></div><div class="p-inline"><span class="p-badge" :class="order.status">{{statuses[order.status]}}</span><span v-if="final" class="p-badge">Estado final</span></div></header><div v-if="order.paymentIssue" class="p-error">{{order.paymentIssue}}</div><div class="p-two-column"><div><section class="p-section-card"><div class="p-section-title"><h2>Productos</h2><span class="p-badge">{{order.items.length}} líneas</span></div><div class="p-table-scroll"><table class="p-table"><thead><tr><th>Producto</th><th>Precio</th><th>Cantidad</th><th>Total</th></tr></thead><tbody><tr v-for="(item,i) in order.items" :key="i"><td><div class="p-product-cell"><img v-if="item.image" :src="item.image" class="p-product-thumb" alt=""/><span><strong>{{item.name}}</strong><small>{{item.variantName||''}} {{item.type==='digital'?'· Digital':''}}</small></span></div></td><td>{{money(item.unitPrice)}}</td><td>{{item.quantity}}</td><td><strong>{{money(item.lineTotal)}}</strong></td></tr></tbody></table></div></section><section class="p-section-card"><div class="p-section-title"><h2>Cliente y entrega</h2><Icon name="truck" :size="19"/></div><div class="p-form-grid"><div class="p-field"><label>Cliente</label><strong>{{order.customer.name}}</strong><a :href="`mailto:${order.customer.email}`" class="p-help">{{order.customer.email}}</a><span class="p-help">{{order.customer.phone}}</span></div><div class="p-field"><label>Entrega</label><strong>{{order.delivery?.name}}</strong><span class="p-help">{{order.customer.address}}<template v-if="order.customer.city">, {{order.customer.city}}</template> {{order.customer.postalCode}}</span><span class="p-help">{{order.delivery?.description}}</span></div><div v-if="order.customer.notes" class="p-field full"><label>Notas del cliente</label><p class="p-help p-break">{{order.customer.notes}}</p></div></div></section><section class="p-section-card"><div class="p-section-title"><div><h2>Cobro y comprobante</h2><p>{{order.payment?.name}}</p></div><Icon name="credit" :size="19"/></div><p v-if="order.payment?.instructions" class="p-help p-break">{{order.payment.instructions}}</p><div v-if="order.payment?.type==='transfer'" class="p-info">{{order.payment.bank?.bank}} · {{order.payment.bank?.holder}}<br/>Alias: {{order.payment.bank?.alias||'—'}}<br/>CBU/CVU: {{order.payment.bank?.cbu||'—'}}</div><a v-if="order.receipt" :href="`/api${path}/receipt`" class="btn btn-secondary" target="_blank" rel="noopener"><Icon name="download" :size="16"/>Ver comprobante {{order.receipt.name?`· ${order.receipt.name}`:''}}</a><p v-else-if="order.payment?.type==='transfer'" class="p-help">El cliente todavía no adjuntó un comprobante.</p><div v-if="isMP" class="p-info">Los pagos con Mercado Pago se confirman después de verificarlos con la plataforma. La vuelta del navegador a la tienda no confirma el cobro.</div><button v-if="isMP&&order.status!=='paid'" class="btn btn-secondary" :disabled="busy" @click="verify"><Icon name="refresh" :size="15"/>Verificar pago con Mercado Pago</button><a v-if="order.checkoutUrl&&order.status!=='paid'&&order.status!=='cancelled'" :href="order.checkoutUrl" target="_blank" rel="noopener" class="btn btn-text">Abrir enlace de pago <Icon name="external" :size="14"/></a></section><section v-if="order.items.some(i=>i.type==='digital')" class="p-section-card"><div class="p-section-title"><h2>Entrega digital</h2><span class="p-badge" :class="order.digitalDeliveryStatus==='sent'?'green':order.digitalDeliveryStatus==='failed'?'red':'orange'">{{({sent:'Enviada',pending:'Pendiente',failed:'Requiere revisión',not_applicable:'Sin entrega'})[order.digitalDeliveryStatus]||'Pendiente de pago'}}</span></div><p class="p-help">Los enlaces se envían a {{order.customer.email}} cuando el pedido queda pagado.</p><div v-if="order.digitalDeliveryError" class="p-error">{{order.digitalDeliveryError}}</div><button v-if="order.status==='paid'" class="btn btn-secondary" :disabled="busy" @click="resend"><Icon name="mail" :size="15"/>Reintentar / reenviar entrega</button></section><section class="p-section-card"><div class="p-section-title"><h2>Historial del pedido</h2></div><div v-for="(event,i) in order.history||[]" :key="i" class="p-activity-item"><span><Icon name="check" :size="14"/></span><div><strong>{{statuses[event.status]||fulfillments[event.fulfillmentStatus||event.status?.replace('delivery:','')]||event.action||'Actualización'}}</strong><small>{{date(event.at||event.createdAt)}}</small><p v-if="event.note" class="p-help p-break">{{event.note}}</p></div></div><p v-if="!order.history?.length" class="p-help">Pedido registrado.</p></section></div><aside class="p-order-summary"><h3>Resumen del pedido</h3><div class="p-summary-line"><span>Productos</span><strong>{{money(order.subtotal)}}</strong></div><div class="p-summary-line"><span>Entrega</span><strong>{{money(order.deliveryCost)}}</strong></div><div class="p-summary-line total"><span>Total</span><strong>{{money(order.total)}}</strong></div><hr class="p-separator"/><div class="p-field"><label for="order-status">Estado del pedido</label><select id="order-status" v-model="nextStatus" :disabled="final||busy"><option v-for="(label,value) in statuses" :key="value" :value="value" :disabled="isMP&&value==='paid'">{{label}}{{['paid','cancelled'].includes(value)?' · final':''}}</option></select><p v-if="final" class="p-help">Este estado es final y no puede revertirse.</p></div><div v-if="!final" class="p-form-actions"><button class="btn btn-primary" style="width:100%" :disabled="busy||nextStatus===order.status" @click="status">Actualizar pedido</button></div><hr class="p-separator"/><div class="p-field"><label for="fulfillment-status">Estado de la entrega</label><select id="fulfillment-status" v-model="nextFulfillment" :disabled="busy||order.status==='cancelled'"><option v-for="(label,value) in fulfillments" :key="value" :value="value" :disabled="order.status!=='paid'&&['shipped','delivered'].includes(value)">{{label}}</option></select><small>Confirmá el cobro antes de marcar como enviado o entregado. La entrega se gestiona por separado del pago.</small></div><div class="p-form-actions"><button class="btn btn-secondary" style="width:100%" :disabled="busy||nextFulfillment===order.fulfillmentStatus||order.status==='cancelled'" @click="fulfillment">Actualizar entrega</button></div><div class="p-field"><label for="order-note">Nota para el historial</label><textarea id="order-note" v-model="note" rows="3" maxlength="1000" placeholder="Detalle del cambio..."/></div></aside></div></template></div></template>
